STANDARD_RECIPES = {'糖醋排骨': {'category': '肉类', 'base_amount': 500.0, 'base_unit': 'g', 'ingredients': [('主材', '排骨', 500, ''), ('糖色', '糖色', 20, ''), ('爆香', '葱花', 5, ''), ('爆香', '蒜片', 3, ''), ('爆香', '料酒', 20, ''), ('爆香', '生抽', 20, ''), ('配料', '盐', 2.5, ''), ('配料', '冰糖', 15, ''), ('配料', '6度白醋', 15, ''), ('配料', '白芝麻', 5, '')], 'steps': [(1, '主材准备', '1.排骨：500g\n2.焯水：冷水下锅，葱段，姜片，料酒，开锅后2分钟捞出，凉水洗去浮沫\n3.擦干：尽可能擦干水分，晾干', ''), (2, '配料准备', '1.小料：葱花5g，蒜片3个\n2.糖色：30g油法，倒入高压锅', ''), (3, '主材处理', '1.煎炒：中火，放入排骨煎炒，持续搅拌，煎至微微金黄，过程适时降低火力或者离火，保证不产生明显烟雾，煎好后盛出', ''), (4, '整体制作', '1.爆香：少许底油，葱、蒜爆香，放入排骨，翻炒均匀；料酒20g，生抽20g，爆香后加水，差不多没过排骨即可，不用太多；然后整个倒入高压锅，盐3g，上气后转最小火，炖15分钟\n2.收汁：倒入炒锅，中高火烧开，冰糖15g，收汁一半时转中火，不要用力翻拌，防止拌碎，汁差不多后转小火，锅边6度白醋20g，搅拌均匀，白芝麻5g，出锅', '3.火不要大，容易糊锅')], 'source_sheet': '糖醋排骨'}, '尖椒干豆腐': {'category': '家常', 'base_amount': 250.0, 'base_unit': 'g', 'ingredients': [('主材', '豆腐皮', 250, ''), ('主材', '尖椒', 100, ''), ('主材', '五花肉', 100, ''), ('腌肉', '清水', 2000, ''), ('腌肉', '小苏打', 1, ''), ('碗汁', '五花肉', 100, ''), ('碗汁', '葱花', 5, ''), ('碗汁', '姜末', 2, ''), ('碗汁', '料酒', 10, ''), ('碗汁', '青椒', 100, ''), ('爆香', '开水', 500, ''), ('爆香', '生抽', 20, ''), ('爆香', '鸡精', 2, ''), ('爆香', '味精', 2, ''), ('爆香', '盐', 6, ''), ('出锅', '淀粉', 20, ''), ('出锅', '清水', 100, ''), ('出锅', '蒜末', 6, '')], 'steps': [(1, '主材准备', '1.主材：豆腐皮250g，尖椒100g，两者比例2.5:1，五花肉100g\n2.改刀：豆腐皮6厘米长，3厘米宽；尖椒，滚刀块，清洗掉籽；五花肉：三毫米厚', ''), (2, '配料准备', '1.小料：葱花5cm，姜末2片，蒜末6个\n2.淀粉水：玉米淀粉20g，清水100g', ''), (3, '主材处理', '1.焯水：清水开锅后放入豆腐皮，炖5分钟；加入1g小苏打，再炖1分钟，捞出放入清水中浸泡', '1.放碱的作用是让干豆腐变得滑嫩，在碱水中煮的时间越长越嫩，但也存在煮烂的风险。所以，放碱不是必须的，如果干豆腐本身比较嫩就不用放。只不过一般都不会太嫩。\n2.干豆腐已经嫩的标准，拿起来很有弹性，抖抖嗖嗖的'), (4, '整体制作', '1.爆锅：油40g，肉片炒香；葱花，姜末，炒香；料酒10g；翻入青椒，炒软\n2.炖煮：开水500g（豆腐皮两倍），生抽20g，鸡精2g，味精1g，盐4g，炖煮\n3.勾芡：底部汤汁剩200g开始勾芡，多次勾芡，装盘后周围能流出一圈汁为标准\n4.出锅：关火，加入蒜末，翻炒几下出锅', '')], 'source_sheet': '尖椒干豆腐'}, '西红柿鸡蛋汤': {'category': '汤', 'base_amount': 300.0, 'base_unit': 'g', 'ingredients': [('主材', '西红柿', 300, ''), ('配料', '清水', 1000, ''), ('配料', '淀粉', 30, ''), ('配料', '清水', 150, ''), ('配料', '鸡蛋', 1, ''), ('配料', '盐', 6, ''), ('配料', '白胡椒粉', 1, ''), ('配料', '味精', 2, ''), ('配料', '香油', 3, ''), ('配料', '香菜', 0.5, '')], 'steps': [(1, '主材准备', '1.西红柿：300g', ''), (2, '配料准备', '1.清水：1000g\n2.淀粉水：玉米淀粉30g，清水150g\n3.鸡蛋：1个\n4.香菜：半棵切段', ''), (3, '主材处理', '1.西红柿：平放，切成八份，不要切到低，然后侧放，切成小丁，再多切几下，把西红柿丁切的尽量小\n2.鸡蛋：打入碗中备用，不能提前打散', ''), (4, '整体制作', '1.水烧开后放入西红柿丁，大火煮5分钟\n2.中火，分次加入淀粉水，加入一次后搅拌，观察粘稠度\n3.鸡蛋打散\n4.最小火或者关火，慢慢转圈倒入蛋液，加蛋液的同时搅拌，让蛋液均匀扩散\n5.最小火，加入盐6g，白胡椒粉1g，味精2g，搅拌均匀，香油3g，加入香菜，搅拌均匀，出锅', '')], 'source_sheet': '西红柿鸡蛋汤'}, '红烧肉': {'category': '肉类', 'base_amount': 500.0, 'base_unit': 'g', 'ingredients': [('主材', '五花肉', 500, ''), ('小料', '糖色（嫩）', 25, ''), ('糖色', '葱段', 4, ''), ('糖色', '姜片', 3, ''), ('糖色', '八角', 1, ''), ('糖色', '香叶', 2, ''), ('爆香', '料酒', 30, ''), ('爆香', '生抽', 20, ''), ('爆香', '热水', 500, ''), ('爆香', '盐', 2.5, ''), ('出锅', '味精', 2, '')], 'steps': [(1, '主材准备', '1.五花肉：350g\n2.改刀：3cm见方\n3.焯水：冷水下锅，姜片、料酒，开锅后2分钟，捞出温水洗净', ''), (2, '配料准备', '1.小料：葱段4cm，姜片3片，八角1个，香叶2片', ''), (3, '主材处理', '', ''), (4, '整体制作', '1.糖色：20g，嫩色\n2.下肉：小火，糖色达标后立刻下入五花肉，翻炒均匀；放入香料，中火，翻炒均匀；料酒20g，生抽15g，翻炒均匀\n3.初炖：加入热水，刚刚没过主材即可，炖15分钟\n4.压炖：放入高压锅，水量与主材齐平即可，盐1.5g，上气后转小火炖15分钟\n5.收汁：放入炒菜锅中，大火，收汁一半时转中火，汁差不多后转小火，出锅前味精2g', '')], 'source_sheet': '红烧肉'}, '锅包肉': {'category': '肉类', 'base_amount': 400.0, 'base_unit': 'g', 'ingredients': [('主材', '外脊', 400, ''), ('腌肉', '土豆淀粉', 250, ''), ('腌肉', '清水', 250, ''), ('碗汁', '白糖', 80, ''), ('碗汁', '6度米醋', 80, ''), ('碗汁', '生抽', 5, ''), ('碗汁', '盐', 3, ''), ('碗汁', '香油', 8, ''), ('爆香', '胡萝卜丝', 2, ''), ('爆香', '香菜杆', 0.5, ''), ('出锅', '葱丝', 5, ''), ('出锅', '姜丝', 2, ''), ('出锅', '大蒜片', 4, '')], 'steps': [(1, '主材准备', '1.外脊：400g\n2.湿淀粉：土豆淀粉250g加等量水250g，搅拌后静止1小时以上，至淀粉沉淀水完全清澈，倒出上层水后备用', ''), (2, '配料准备', '1.碗汁：白糖90g，9度米醋60g，生抽5g，盐2g，淀粉水12g（玉米淀粉2g，清水10g）\n2.配菜：香菜半棵切段（用中段杆），大蒜4颗切片，姜两片切丝，胡萝卜两片切丝，葱段5cm划一刀只留外面葱白切丝', '1.醋的度数越高，酸度越高，因此醋的用量要根据度数，度数越高，用量越少\n2.配菜量不能多，因为含水多；姜丝提味很关键'), (3, '主材处理', '1.改刀：外脊顺纹切成厚片，厚5mm，长8cm，宽4cm\n2.清洗：把肉片清洗一遍，然后尽可能攥干水分，厨房纸擦干盆内水分，肉表面也可以用厨房纸稍微擦一下（不用完全擦干，有的还加水，为了柔嫩）\n3.腌味：盐2g抓拌至盐粒融化，肉微微起胶发粘，腌制15分钟', ''), (4, '整体制作', '1.挂糊：将湿淀粉放入肉片中，加入30g清水（逐次加一点水），加入25g食用油（豆油颜色最好），抓拌均匀，拎起肉片糊不往下滴落\n2.油炸：180度油温，全程大火，炸至定型（拎起肉片在盆里抹几下，保证肉片展开，然后顺着下锅），炸至稍为有一点点露红，捞出，等油温升至200度复炸30秒，捞出，再等油温升至200度（微微冒烟）二次复炸至表面金黄、露肉的地方均呈现枣红色捞出\n3.熬汁：少许底油，葱、姜、蒜爆香，大火，加入碗汁，快速搅拌熬至起泡\n4.出锅：胡萝卜丝和香菜段与肉放在一起，放入肉，抬起锅快速翻匀出锅', '1.每100g干淀粉加10g食用油；糊的稠度大于酸奶状\n2.肉片放入后3秒立刻上浮说明油温正确')], 'source_sheet': '锅包肉'}, '水饺': {'category': '主食', 'base_amount': 350.0, 'base_unit': 'g', 'ingredients': [('主材', '琵琶腿', 350, '')], 'steps': [(1, '主材准备', '1.葱姜水：花椒3g，开水300g，水温后，加入葱20g，姜15g，稍为抓拌，过滤出250g备用\n2.猪肉500g，绞肉机打碎，加入食用碱1g，盐8g，抓匀，按一个方向打至发粘，然后分5次加入葱姜水，每次都是按一个方向打至发粘，保证水分完全吸收再加下一次水\n3.调味：生抽10g，老抽5g，蚝油20g，十三香1g，味精3g，鸡精2g，白糖3g，搅拌均匀，食用油30g，搅拌均匀，香油10g，搅拌均匀，冰箱冷藏\n4.白菜：白菜500g，切碎，盐10g，抓拌均匀，静置10分钟杀水，清水淘洗3遍，纱布挤干水分后大约250g，加入食用油10g', ''), (2, '配料准备', '1.面粉480g，土豆淀粉20g，盐3g，凉水260g', ''), (3, '主材处理', '', ''), (4, '整体制作', '', '')], 'source_sheet': '水饺'}, '照烧鸡腿': {'category': '肉类', 'base_amount': 350.0, 'base_unit': 'g', 'ingredients': [('主材', '琵琶腿', 350, ''), ('腌肉', '葱姜水', 10, ''), ('腌肉', '盐', 1.2, ''), ('腌肉', '鸡精', 1.2, ''), ('腌肉', '味精', 1.2, ''), ('腌肉', '胡椒粉', 1.2, ''), ('碗汁', '清水', 120, ''), ('碗汁', '生抽', 12, ''), ('碗汁', '老抽', 4, ''), ('碗汁', '白糖', 10, ''), ('碗汁', '料酒', 8, ''), ('碗汁', '鸡精', 2, ''), ('碗汁', '番茄酱', 10, ''), ('其他', '玉米淀粉', 1, ''), ('翻炒', '蒜片', 5, ''), ('翻炒', '郫豆瓣酱', 5, ''), ('翻炒', '料油', 5, '')], 'steps': [(1, '主材准备', '1.琵琶腿：4根，350g（去骨后）\n2.改刀：用剪刀将骨头剔除，从最厚处贴着骨头剪开，以便展开后尽可能厚度一致；横着、竖着改刀，不要切断，可以密一点，整体上越平越好，尤其是肉厚的地方\n3.腌味：葱姜水10g，盐1g，鸡精1g，味精1g，胡椒粉1g，抓匀后腌制5分钟', '鸡腿横着改刀，可以防止加热后收缩'), (2, '配料准备', '1.碗汁：清水100g，生抽10g，老抽5g，白糖10g，鸡精2g，番茄酱10g\n2.郫县豆瓣10g\n3.蒜5个，切碎', ''), (3, '主材处理', '1.拍粉：盘子中铺一层玉米淀粉,主材展开挂粉，带鸡皮的一面不挂，挂完后尽量把粉抖干净，薄薄的一层即可\n2.煎肉：放入煎锅煎,小火,适时翻面，如果太溅油，可以先盖盖焖熟\n3.上色：打开盖子，煎至金黄,表面变硬,后期可视情况转中火\n4.切条：放至不烫后切成长条块', ''), (4, '整体制作', '1.植物油少许,小火,放蒜炒香\n2.放郫县豆瓣酱，炒香\n3.加碗汁,中高火,搅拌,开锅后再搅拌一会\n4.放入主材翻炒,中高火收汁,收至底部剩50g汁出锅', '')], 'source_sheet': '照烧鸡腿'}, '红烧鲈鱼': {'category': '鱼类', 'base_amount': 540.0, 'base_unit': 'g', 'ingredients': [('主材', '鲈鱼', 540, ''), ('腌肉', '葱姜料酒', 10, ''), ('腌肉', '盐', 1.5, ''), ('碗汁', '姜', 2, ''), ('碗汁', '大葱', 5, ''), ('碗汁', '大蒜', 4, ''), ('碗汁', '八角', 1, ''), ('碗汁', '花椒', 3, ''), ('碗汁', '二荆条', 5, ''), ('爆香', '陈醋', 5, ''), ('爆香', '生抽', 20, ''), ('爆香', '白糖', 3, ''), ('爆香', '老抽', 3, ''), ('爆香', '鸡精', 2, ''), ('爆香', '蚝油', 10, ''), ('出锅', '香菜', 0.5, ''), ('出锅', '味精', 2, ''), ('出锅', '香油', 5, '')], 'steps': [(1, '主材准备', '1.鲈鱼：一条540g，清洗、处理干净；放入鱼盘，将鱼表面和内部水分擦干\n2.腌肉：葱姜料酒10g和盐1.5g，混合溶解后均匀涂抹在鱼身和内部，腌制15分钟', '1.擦干有助于腌肉\n2.料酒用量以均匀涂满鱼身为准，下面不要富余太多'), (2, '配料准备', '1.小料：姜2片切丝，大葱5cm切厚片，大蒜4个切片，八角1个，花椒3g，二荆条辣椒5cm切段\n2.配料：香菜半棵', ''), (3, '主材处理', '1.擦干：将腌过的鱼里外擦干水分\n2.煎鱼：炒菜量食用油，中高火，轻微冒烟后放入鱼（先放尾巴，然后顺着滑入），先不要动鱼，煎1分钟后来回转锅让油煎到鱼头和鱼尾，煎3分钟后翻面，同样方法煎另一面，两面煎至金黄，可根据颜色再次翻面；煎好后盛出备用', ''), (4, '整体制作', '1.爆香：少量食用油，中火，炒菜量猪油，融化后转小火，放入小料炒香，放入郫县豆瓣酱10g，炒出红油\n2.炖鱼：放入鱼，中火，陈醋5g爆香，生抽20g爆香，大火，加开水（水量没过鱼身三分之二），白糖3g，老抽3g，鸡精2g，蚝油10g，中小火，炖15分钟\n3.收汁：大火，加入香菜，一遍收汁一遍用勺把汤汁往鱼上面淋，过程中可根据颜色加老抽，收到一半时加入味精2g，香油5g，继续收汁至出锅', '')], 'source_sheet': '红烧鲈鱼'}, '糖醋里脊': {'category': '肉类', 'base_amount': 300.0, 'base_unit': 'g', 'ingredients': [('主材', '里脊', 300, ''), ('腌肉', '盐', 1, ''), ('腌肉', '白胡椒粉', 0.3, ''), ('腌肉', '葱姜料酒', 5, ''), ('碗汁', '白糖', 40, ''), ('碗汁', '5度白醋', 40, ''), ('碗汁', '陈醋', 10, ''), ('碗汁', '生抽', 10, ''), ('碗汁', '老抽', 3, ''), ('碗汁', '盐', 1, ''), ('碗汁', '淀粉', 5, ''), ('碗汁', '清水', 25, ''), ('爆香', '玉米淀粉', 120, ''), ('爆香', '面粉', 40, ''), ('爆香', '清水', None, ''), ('爆香', '植物油', 20, ''), ('出锅', '姜末', 3, ''), ('出锅', '蒜片', 3, ''), ('出锅', '葱花', 5, '')], 'steps': [(1, '主材准备', '1.改刀：外脊顺纹切成肉片，再切成肉条，粗1.5cm，长5cm\n2.清洗：把肉条清洗一遍，然后尽可能攥干水分，厨房纸擦干盆内水分，肉表面也可以用厨房纸稍微擦一下（不用完全擦干，有的还加水，为了柔嫩）\n3.腌味：盐1g，白胡椒粉0.3g，葱姜料酒5g，抓拌均匀至微微起胶发粘，腌制15分钟', ''), (2, '配料准备', '1.碗汁：白糖40g，5度白醋40g，陈醋10g，生抽10g，老抽3g，盐1g，淀粉5g，清水25g\n2.小料：姜末3g，蒜片3个，葱花5g\n3.调糊：线糊（玉米淀粉120g，面粉40g），食用油20g', ''), (3, '主材处理', '1.挂糊：线糊（玉米淀粉120g，面粉40g），肉条放入抓拌均匀，加入食用油20g抓拌均匀\n2.初炸：油温160度，小火（工作油温150度左右），炸至有的地方发黄捞出，约3分钟，两锅下\n3.复炸：中火，油温190度，炸至金黄，部分位置枣红色捞出，约1分钟', ''), (4, '整体制作', '1.爆锅：少许底油，加入小料炒香\n2.熬汁：中火，加入碗汁，搅拌至粘稠\n3.出锅：关火，放入主材，翻拌均匀，撒入白芝麻，翻版均匀出锅', '')], 'source_sheet': '糖醋里脊'}, '姜丝炸鸡': {'category': '肉类', 'base_amount': 400.0, 'base_unit': 'g', 'ingredients': [('主材', '鸡腿肉', 400, ''), ('腌肉', '水淀粉', 300, ''), ('碗汁', '生抽', 23, ''), ('碗汁', '花椒', 2, ''), ('碗汁', '料酒', 10, ''), ('爆香', '姜', 40, ''), ('爆香', '生抽', 5, ''), ('爆香', '料酒', 5, '')], 'steps': [(1, '主材准备', '1.改刀：剔下肉，清水加面粉清洗，然后冲洗几遍，控水擦干表面水分，切成20g小块\n2.腌肉：生抽26g，花椒2g，料酒10g，腌制20分钟', ''), (2, '配料准备', '1.姜丝：姜40g，切稍为粗一点点的丝，生抽5g，料酒5g，腌制20分钟', ''), (3, '主材处理', '1.混合：姜丝放入鸡肉中抓拌均匀（腌姜丝的汁水不要加入，只要姜丝）\n2.炸鸡：中火油温160度，每块鸡肉都挂上姜丝下锅，炸8分钟捞出，中火油温180度复炸，炸至金黄，大约2分钟出锅', ''), (4, '整体制作', '', '')], 'source_sheet': '姜丝炸鸡'}, '宫保虾球': {'category': '海鲜', 'base_amount': 200.0, 'base_unit': 'g', 'ingredients': [('主材', '虾仁', 200, ''), ('腌肉', '葱姜料酒', 5, ''), ('腌肉', '盐', 0.5, ''), ('腌肉', '白胡椒粉', 0.3, ''), ('碗汁', '生抽', 10, ''), ('碗汁', '老抽', 3, ''), ('碗汁', '白糖', 20, ''), ('碗汁', '陈醋', 20, ''), ('碗汁', '清水', 40, ''), ('碗汁', '玉米淀粉', 8, ''), ('碗汁', '盐', 1, ''), ('碗汁', '香油', 5, ''), ('爆香', '花椒', 2, ''), ('爆香', '大蒜片', 3, ''), ('爆香', '姜丝', 1, ''), ('爆香', '二荆条', 5, ''), ('出锅', '葱段', 60, ''), ('出锅', '腰果/花生', 50, '')], 'steps': [(1, '主材准备', '1.虾仁：200g，12个\n2.改刀：清洗后，虾背片一刀，二分之一深度；去除虾线，清洗，用厨房纸擦干水分\n3.腌味：盐1g（三分口），白胡椒粉0.3g（不能多），葱姜料酒5g，抓匀，腌制5分钟', '3.白胡椒粉不能多，腌味用了盐和料酒，碗汁就不加了，增加层次'), (2, '配料准备', '1.碗汁：生抽10g，老抽3g，白糖20g，陈醋20g，清水40g，玉米淀粉8g\n2.小料：花椒2g，大蒜3个，姜丝5条，干辣椒少许\n3.葱段：60g，手掌长、大拇指粗，切成2厘米葱段\n4.腰果：50g，正常一把', ''), (3, '主材处理', '1.初炸：用一个盘子装玉米淀粉，虾仁一个一个拿进盘子里蘸淀粉，全部蘸完后在开始炸（不是蘸一个往里放一个）；玉米油160度下锅，大火，全部放入后炸1分钟定型捞出\n2.复炸：180度复炸30秒', '1.全部蘸完后在开始炸有两个好处，一是开始保证同时下锅，二是可以增加放置时间，虾蘸淀粉后放置一会有利于淀粉蘸的更牢固'), (4, '整体制作', '1.爆香：少许底油，小火放花椒，出香变色后捞出；放入姜、蒜，放入葱段，炒香\n2.熬汁：大火，加入碗汁，烧开后小火\n3.出锅：放入虾球，拌均，放入腰果，拌均，根据汁水量，适时出锅', '因为有淀粉所以不需过长时间熬汁')], 'source_sheet': '宫保虾球'}, '萝卜丸子': {'category': '家常', 'base_amount': 500.0, 'base_unit': 'g', 'ingredients': [('主材', '青萝卜', 500, ''), ('主材', '胡萝卜', 150, '')], 'steps': [(1, '主材准备', '1.改刀：青萝卜500g擦中丝，胡萝卜150g擦细丝\n2.脱水：加1.2%盐脱水10分钟，清水淘洗两遍后用纱布挤干水分；脱水后共450g（脱水30%）', ''), (2, '配料准备', '1.配料：葱花20g，姜末10g，香菜末50g(2棵)\n2.面粉：面粉180g，玉米淀粉60g，盐3g，鸡精4g，十三香1g，小苏打0.5g，混合均匀', ''), (3, '主材处理', '1.混合：小料放入萝卜丝中混合均匀（总重），加入混合面粉，搅拌均匀，加入一个鸡蛋，搅拌均匀，视干稀程度再加面粉，至能团成丸子即可\n2.制丸：团成2cm直径丸子（丸子不要太大），摆在案上', ''), (4, '整体制作', '1.初炸：油温180度，转小火，下丸子，油温保持在140-150度，炸大约2分钟至变黄捞出\n2.复炸：转中火，油温180度复炸大约30分钟至金黄（时刻关注颜色，颜色够了即可，炸过容易发苦）', '')], 'source_sheet': '萝卜丸子'}, '酥锅': {'category': '家常', 'base_amount': 350.0, 'base_unit': 'g', 'ingredients': [('主材', '琵琶腿', 350, '')], 'steps': [(1, '主材准备', '白菜围圈，中途幺汤\n葱姜分层', ''), (2, '配料准备', '1.碗汁：生抽120g，老抽20g，白糖80g，5度陈醋80g，料酒60g，盐10g\n2.小料：', ''), (3, '主材处理', '', ''), (4, '整体制作', '1.第一层：骨头，铺满，白菜帮插边\n2.第二层：藕片，铺满\n3.第三层：白菜叶和帮，铺满\n4.第四层：猪蹄，铺满，葱姜\n5.第五层：海带，铺满\n6.第六层：豆腐泡，铺满\n7.第七层：五花肉，铺满，葱姜\n8.第八层：藕片，铺满', '')], 'source_sheet': '酥锅'}, 'Sheet2': {'category': '草稿', 'base_amount': 250.0, 'base_unit': 'g', 'ingredients': [('主材', '琵琶腿', 250, ''), ('配料', '葱姜水', 1, ''), ('配料', '葱花', None, ''), ('配料', '蒜片', None, ''), ('配料', '黄瓜', None, ''), ('配料', '胡萝卜', None, ''), ('配料', '生抽', 8, ''), ('配料', '老抽', 2, ''), ('配料', '清水', 60, ''), ('配料', '淀粉', 3, ''), ('配料', '盐', 1, ''), ('配料', '味精', 2, ''), ('配料', '鸡精', 2, '')], 'steps': [(1, '主材准备', '1.鲅鱼：先切段，大拇指长，再切条，1厘米\n2.腌肉：葱姜水，腌10分钟\n3.湿淀粉：100g', ''), (2, '配料准备', '1.碗汁：生抽8g，老抽2g，清水70g，淀粉3g，盐1g，味精2g，鸡精2g\n2黄瓜：少许，切片，0.5cm厚，大拇指长\n3.胡萝卜：少许，切片\n4.小料：葱花，蒜片', ''), (3, '主材处理', '4.挂糊：全鸡蛋一个，土豆淀粉30g，面粉30g，酸奶状，透着糊能看到鱼肉，但不滴\n1.炸肉：中高火，油温180度，炸至金黄色，复炸', ''), (4, '整体制作', '1.爆锅：葱蒜，炒香，黄瓜片、胡萝卜片，料酒10g\n2.碗汁\n3.出锅：香油', '')], 'source_sheet': 'Sheet2'}, '椒盐鸡翅': {'category': '肉类', 'base_amount': 300.0, 'base_unit': 'g', 'ingredients': [('主材', '翅中', 300, ''), ('腌肉', '葱姜水', 1, ''), ('腌肉', '花雕酒', 5, ''), ('腌肉', '白糖', 2, ''), ('腌肉', '白胡椒粉', 5, ''), ('腌肉', '生抽', 5, ''), ('腌肉', '盐', 2, '')], 'steps': [(1, '主材准备', '1.翅中：300g，10个，清洗或解冻后擦干水分\n2.改刀：两面划几刀或一分为二\n3.腌味：葱姜水，花雕酒5g，白糖2g，白胡椒粉5g，生抽5g，盐2g', ''), (2, '配料准备', '1.炸糊：土豆淀粉30g，面粉30g，泡打粉2.5g（泡打粉4%），顺逆来回搅拌或Z字搅拌，因为有面粉所以不能打圈搅拌，面糊上劲，面筋会崩油。状态为酸奶状（介于普通酸奶和老酸奶之间），挂上后会滴下但不成线，俗称哩哩啦啦', ''), (3, '主材处理', '', ''), (4, '整体制作', '', '')], 'source_sheet': '椒盐鸡翅'}, '空气炸锅鸡翅': {'category': '肉类', 'base_amount': 350.0, 'base_unit': 'g', 'ingredients': [('主材', '鸡翅中', 350, ''), ('腌肉', '葱姜水', 5, ''), ('腌肉', '花雕酒', 5, ''), ('腌肉', '白糖', 2, ''), ('腌肉', '白胡椒粉', 5, ''), ('腌肉', '生抽', 5, ''), ('腌肉', '盐', 2, '')], 'steps': [(1, '主材准备', '1.翅中：300g，10个，清洗或解冻后擦干水分\n2.改刀：两面划几刀或一分为二\n3.腌味：葱姜水，花雕酒5g，白糖2g，白胡椒粉5g，生抽5g，盐2g', ''), (2, '配料准备', '', ''), (3, '主材处理', '', ''), (4, '整体制作', '1.初烤：空气炸锅预热2分钟，200度13分钟\n2.翻面：180度10分钟\n3.定色：初炸和翻面后基本熟了，根据颜色再多烤几分钟\n4.撒料：两面撒上椒盐或烧烤料，160度2分钟', '')], 'source_sheet': '空气炸锅鸡翅'}, '寿司': {'category': '主食', 'base_amount': 300.0, 'base_unit': 'g', 'ingredients': [('主材', '大米', 300, ''), ('蒸米', '清水', 300, ''), ('寿司醋', '盐', 4, ''), ('寿司醋', '白糖', 20, ''), ('寿司醋', '3.5米醋', 40, ''), ('卷料', '黄瓜', 1, ''), ('卷料', '胡萝卜', 1, ''), ('卷料', '火腿肠', 1, ''), ('酱料', '沙拉', 1, ''), ('酱料', '番茄酱', 1, '')], 'steps': [(1, '主材准备', '1.大米：300g，淘洗两遍，侵泡20分钟，沥干水分\n2.蒸米：加水300g，电饭煲蒸米饭，蒸熟后闷10分钟', '1.尽可能沥干水分，沥干后含水量约50g\n2.整个水量为大米1.1倍，闷10分钟是为了减少水分（也可以不闷）'), (2, '配料准备', '1.黄瓜条：\n2.萝卜条：\n3.火腿肠条：', ''), (3, '主材处理', '1.搅拌：米饭蒸熟后电饭煲端出，先掏底搅拌，然后一边淋醋汁一边将米粒搅拌开，不要压米饭，保证颗粒分明最好\n2.降温：搅拌均匀后放置晾凉至45度', ''), (4, '整体制作', '1.竹帘包保鲜膜，一张海苔，亮面向下，近端与竹帘1cm距离，方便按压\n2.米饭200g均匀铺满，远端留空1cm不放米饭，近端齐平，轻轻按压紧实\n3.配料均匀摆放在中间位置，挤上沙拉，番茄酱，放肉松\n4.拇指食指捏起竹帘，其他手指按住配料，卷起，空出的1cm竹帘按压，形成一个基础盒，然后顺势卷过去', '')], 'source_sheet': '寿司'}, '砸鱼汤': {'category': '汤', 'base_amount': 500.0, 'base_unit': 'g', 'ingredients': [('主材', '红烧鲈鱼', 500, ''), ('配料', '花椒', 2, ''), ('配料', '葱姜蒜', 1, ''), ('配料', '海米', 8, ''), ('配料', '米醋3.5', 40, ''), ('配料', '开水', 1000, ''), ('配料', '生抽', 10, ''), ('配料', '盐', 6, ''), ('配料', '糖', 3, ''), ('配料', '白胡椒粉', 25, ''), ('配料', '米醋3.5', 30, ''), ('配料', '味精', 4, ''), ('配料', '鸡精', 2, ''), ('配料', '鸡蛋', 2, ''), ('配料', '香菜', 1, ''), ('配料', '香油', 5, '')], 'steps': [(1, '主材准备', '1.汤底：红烧鲈鱼（带汤）\n2.鸡蛋：2个\n3.开水：1000g', ''), (2, '配料准备', '1.葱姜蒜，花椒2g，海米10个，香菜\n2.白胡椒粉20g，3.5度米醋100g，白糖3g', ''), (3, '主材处理', '1.鸡蛋2个：打入碗中备用，不能打散', ''), (4, '整体制作', '1.爆香：小火，花椒炒香捞出，葱姜蒜炒香，放入海米，炒香\n2.烹醋：中火，加入米醋50g，烧至沸腾后加入开水\n3.炖汤：不等开锅，加入汤底，烧开\n4.调味：生抽10g，盐6g，糖3g，咸度调好后再调酸度，米醋30g，调好酸度后再辣酸，白胡椒粉25g，味精6g，鸡精2g\n5.出锅：淋入蛋液，搅拌均匀，加入香菜，加入5g香油或料油，搅拌后出锅', '')], 'source_sheet': '砸鱼汤'}}